VAR
    Overload_Timer : TON;
END_VAR

Overload_Timer(IN := (Motor_Current > 51.9) AND Motor_Running, PT := T#3S);

IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Motor_Stop := FALSE;
    Overload_Alarm := FALSE;
END_IF;

